('Man | 3000 | Afwisselen','man','breakfast=ontA:hav90,kwa350,bos100;lunch=lunA:wra180,eic300,tom40,sla30,ol55,kpl30;snack1=appel:app180;dinner=din1:zaa500,brc200,kip140,avo50,ole15;snack2=cot:cra25,cot200/breakfast=ontB:kom40,ban120,ei8240,bro175,kpl105,bes60;lunch=lunB:che110,kom90,kip120,ol715,pas115;snack1=appel:app180;dinner=din2:spi200,zaa100,kip100,ol715,rij100;snack2=cot:cra25,cot200/breakfast=ontA:hav90,kwa400,bos100;lunch=lunA:wra180,eic300,tom40,sla30,ol55,kpl30;snack1=appel:app180;dinner=din3:brc200,ter40,kip110,rij130,ole15;snack2=cot:cra25,cot200/breakfast=ontB:kom40,ban120,ei8240,bro210,kpl75,bes60;lunch=lunB:che110,kom90,kip110,ol715,pas135;snack1=appel:app180;dinner=din4:spi100,kip130,kri425,ole15;snack2=cot:cra25,cot200'),
