('Vrouw | 1600 | Afwisselen','vrouw','breakfast=ontA:hav25,kwa450,bos100;lunch=lunA:wra60,eic180,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa150,brc200,kip160,ole15/breakfast=ontB:kom40,ban120,ei860,bro35,kpl135,bes60;lunch=lunB:che110,kom90,kip160,ol715,pas40;snack1=appel:app180;dinner=din2:spi200,zaa100,kip130,ol715,rij30/breakfast=ontA:hav25,kwa450,bos100;lunch=lunA:wra60,eic180,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din3:brc200,ter40,kip140,rij30,ole15/breakfast=ontB:kom40,ban120,ei860,bro70,kpl120,bes60;lunch=lunB:che110,kom90,kip140,ol715,pas45;snack1=appel:app180;dinner=din4:spi100,kip170,kri150,ole10'),
