('Vrouw | 1800 | Vast 3 maaltijden','vrouw','breakfast=ontA:hav35,kwa450,bos100;lunch=lunA:wra120,eic180,tom40,sla30,ol55,kpl45;dinner=din1:zaa250,brc200,kip150,ole15'),
('Vrouw | 1800 | Afwisselen','vrouw','breakfast=ontA:hav25,kwa450,bos100;lunch=lunA:wra120,eic180,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa175,brc200,kip160,ole15/breakfast=ontB:kom40,ban120,ei860,bro70,kpl150,bes60;lunch=lunB:che110,kom90,kip160,ol715,pas40;snack1=appel:app180;dinner=din2:spi200,zaa100,kip140,ol715,rij35/breakfast=ontA:hav40,kwa500,bos100;lunch=lunA:wra60,eic180,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din3:brc200,ter40,kip140,rij60,ole15/breakfast=ontB:kom40,ban120,ei8120,bro105,kpl105,bes60;lunch=lunB:che110,kom90,kip130,ol715,pas55;snack1=appel:app180;dinner=din4:spi100,kip160,kri175,ole10'),
('Vrouw | 2000 | Vast','vrouw','breakfast=ontA:hav45,kwa400,bos100;lunch=lunA:wra120,eic240,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa250,brc200,kip150,ole15'),
('Vrouw | 2000 | Vast 3 maaltijden','vrouw','breakfast=ontA:hav55,kwa400,bos100;lunch=lunA:wra120,eic240,tom40,sla30,ol55,kpl45;dinner=din1:zaa325,brc200,kip140,ole15'),
('Vrouw | 2000 | Afwisselen','vrouw','breakfast=ontA:hav45,kwa400,bos100;lunch=lunA:wra120,eic240,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa250,brc200,kip150,ole15/breakfast=ontB:kom40,ban120,ei8120,bro105,kpl120,bes60;lunch=lunB:che110,kom90,kip150,ol715,pas55;snack1=appel:app180;dinner=din2:spi200,zaa100,kip120,ol715,rij50/breakfast=ontA:hav45,kwa500,bos100;lunch=lunA:wra120,eic180,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din3:brc200,ter40,kip130,rij65,ole15/breakfast=ontB:kom40,ban120,ei8120,bro105,kpl120,bes60;lunch=lunB:che110,kom90,kip130,ol715,pas75;snack1=appel:app180;dinner=din4:spi100,kip160,kri225,ole15'),
('Vrouw | 2200 | Vast','vrouw','breakfast=ontA:hav70,kwa300,bos100;lunch=lunA:wra120,eic300,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa350,brc200,kip130,ole15'),
('Vrouw | 2200 | Vast 3 maaltijden','vrouw','breakfast=ontA:hav85,kwa350,bos100;lunch=lunA:wra120,eic240,tom40,sla30,ol55,kpl45;dinner=din1:zaa450,brc200,kip140,ole15'),
('Vrouw | 2200 | Afwisselen','vrouw','breakfast=ontA:hav70,kwa300,bos100;lunch=lunA:wra120,eic300,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din1:zaa350,brc200,kip130,ole15/breakfast=ontB:kom40,ban120,ei8180,bro140,kpl105,bes60;lunch=lunB:che110,kom90,kip130,ol715,pas65;snack1=appel:app180;dinner=din2:spi200,zaa100,kip100,ol715,rij60/breakfast=ontA:hav65,kwa400,bos100;lunch=lunA:wra120,eic240,tom40,sla30,ol55,kpl45;snack1=appel:app180;dinner=din3:brc200,ter40,kip120,rij85,ole15/breakfast=ontB:kom40,ban120,ei8180,bro140,kpl90,bes60;lunch=lunB:che110,kom90,kip110,ol715,pas90;snack1=appel:app180;dinner=din4:spi100,kip140,kri300,ole15')
  ) as t(naam, groep, dagen) loop
    dagen := string_to_array(r.dagen, '/');
    week := '{}'::jsonb; gk := 0; ge := 0; gkh := 0; gv := 0; nmax := 0;
    for i in 1..7 loop
      d := dagen[((i - 1) % array_length(dagen, 1)) + 1];
      dagobj := '{}'::jsonb; tk := 0; te := 0; tkh := 0; tv := 0; n := 0;
      foreach mtxt in array string_to_array(d, ';') loop
        slot := split_part(mtxt, '=', 1);
        mk := split_part(split_part(mtxt, '=', 2), ':', 1);
        select jsonb_agg(jsonb_build_object('ingredient_id', codes ->> left(x, 3), 'amount', substring(x from 4)::numeric, 'unit', 'gram')) into ingr
          from unnest(string_to_array(split_part(mtxt, ':', 2), ',')) x;
        select to_jsonb(a) into base from ai_meals a where a.id = (mealmap ->> mk)::uuid;
        if base is null then raise exception 'maaltijd ontbreekt: %', mk; end if;
        select * into mac from compute_meal_macros(ingr);
        meal := base || jsonb_build_object('ingredients_list', ingr, 'calories', round(mac.calories), 'protein', round(mac.protein, 1), 'carbs', round(mac.carbs, 1), 'fat', round(mac.fat, 1), 'fiber', round(mac.fiber, 1),
          'original_calories', base -> 'calories', 'original_protein', base -> 'protein', 'original_carbs', base -> 'carbs', 'original_fat', base -> 'fat',
          'slot', slot, 'timing', tijden -> slot ->> 0, 'display_label', tijden -> slot ->> 1, 'meal_id', base ->> 'id', 'meal_name', base ->> 'name');
        dagobj := dagobj || jsonb_build_object(slot, meal);
        tk := tk + round(mac.calories); te := te + mac.protein; tkh := tkh + mac.carbs; tv := tv + mac.fat; n := n + 1;
      end loop;
      dagobj := dagobj || jsonb_build_object('is_training_day', false, 'totals', jsonb_build_object('kcal', round(tk), 'protein', round(te, 1), 'carbs', round(tkh, 1), 'fat', round(tv, 1)));
      week := week || jsonb_build_object(dagnamen[i], dagobj);
      gk := gk + tk; ge := ge + te; gkh := gkh + tkh; gv := gv + tv; nmax := greatest(nmax, n);
    end loop;
    gk := round(gk / 7); ge := round(ge / 7); gkh := round(gkh / 7); gv := round(gv / 7);
    kcal_tr := split_part(r.naam, ' | ', 2)::int; soort := split_part(r.naam, ' | ', 3);
    select id into v_id from meal_plan_templates where name = r.naam and plan_type = 'full_week' and coalesce(is_archived, false) = false order by created_at limit 1;
    if v_id is null then
      insert into meal_plan_templates (coach_id, template_name, name, emoji, description, week_structure, daily_calories, daily_protein, daily_carbs, daily_fat, base_macros, meals_per_day, plan_type, pre_workout_meal, supplements, is_active, is_canoniek, is_archived, doelgroep)
      values (stam.coach_id, r.naam, r.naam, stam.emoji, '', week, gk, ge, gkh, gv, '{}'::jsonb, nmax, 'full_week', stam.pre_workout_meal, stam.supplements, true, true, false, r.groep)
      returning id into v_id;
    end if;
    update meal_plan_templates set week_structure = week, daily_calories = gk, daily_protein = ge, daily_carbs = gkh, daily_fat = gv,
      base_macros = jsonb_build_object('calories', gk, 'protein', ge, 'carbs', gkh, 'fat', gv), meals_per_day = nmax, is_canoniek = true, doelgroep = r.groep,
      description = case soort when 'Vast' then '7 dagen hetzelfde.' when 'Vast 3 maaltijden' then '7 dagen hetzelfde, 3 maaltijden zonder tussendoortje.' else '2 ontbijten en 2 lunches om en om, 4 avondmaaltijden.' end
        || ' Trainingsdag ' || kcal_tr || ' kcal met banaan als pre-workout, rustdag ' || gk || '. ' || case when kcal_tr >= 2600 and r.groep = 'man' then 'Bulk.' else 'Cut of onderhoud.' end,
      updated_at = now()
    where id = v_id;
  end loop;
  update meal_plan_templates set is_archived = true, is_canoniek = false, updated_at = now() where id = '7dc0a4bc-fe32-4597-baf8-73c861cae5a2';
end $$;
